/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: draft, lookup, withApplied, create, reuse
 *   Constants: slotThree
 * Tests
 *   - member rows: an open conflict, a filled member, an answered conflict, and an agreeing member left out, in draft order
 *   - member rows keep each reason a member stays unchanged, a list left out for its characters, length or format with its own, and an unpaired member
 *   - without a single pairing every member is unchanged as unpaired, and without an applied candidate there are no member rows
 *   - expected rows place members by Disc and Track Number, a missing disc as disc 1; members at no row are outside
 *   - a number lookup filled through its pairing is held while the draft keeps it; an answered, edited or unpaired one is not
 *   - answers are made against the saved draft values, an absent value as null
 *   - the decision set sends each edit, else the saved decision without the ID the server binds, and a cleared edit drops its saved decision
 *   - unsaved edits are pruned when their row vanished, was renamed, or now equals the saved decision
 *   - a candidate another identity of the same list is bound to, decided or preselected to reuse is taken; another list takes nothing
 *   - a saved reuse or replace whose record changed since is stale: shown undecided, left out of the saved set and taking nothing; a current one is kept
 * @end-catalog */

import { capturedCatalogReview, slotId, slotTwo } from './catalogReviewFixtures.testSupport';
import { guestCandidateId, guestHandle, leadHandle, leadRecordId, reviewAfterLookup, reviewIdentityResponse, reviewLookupResponse, reviewRows } from './catalogReviewLookupFixtures.testSupport';
import { effectiveDecisions, expectedRowMembers, lookupAnswers, memberRows, pairingFilledNumbers, pruneDecisionEdits, rowDecision, takenCandidates, type DecisionEdit } from './catalogReviewSummaryModel';
import type { ReviewDecisionItem } from './catalogReviewLookupApi';

/** What the review summary derives from the lookup view, the identity read and the saved draft. All data is synthetic. */
const slotThree = '10000000-0000-4000-8000-000000000003';
const draft = () => reviewAfterLookup(capturedCatalogReview()).draft;
const lookup = () => reviewLookupResponse().lookup!;
const withApplied = (edit: (applied: NonNullable<ReturnType<typeof lookup>['applied']>) => void) => { const value = lookup(); edit(value.applied!); return value; };

test('member rows: an open conflict, a filled member, an answered conflict, and an agreeing member left out, in draft order', () => {
  expect(memberRows(lookup(), draft())).toEqual({ paired: true, rows: [
    { slotId, state: 'conflict', conflict: lookup().applied!.conflicts[2] }, { slotId: slotTwo, state: 'filled', entries: draft().tracks[1].artists }] });
  const answered = withApplied(applied => { applied.conflicts[2].answer = 'mine'; });
  answered.needsAnswer.conflicts = ['album.title'];
  expect(memberRows(answered, draft())!.rows[0]).toMatchObject({ slotId, state: 'answered' });
  // A paired member with no value, conflict or flag already agrees with its own release track.
  const agreeing = withApplied(applied => { applied.conflicts.splice(2, 1); applied.values = applied.values.filter(value => !value.path.endsWith('.artists')); });
  expect(memberRows(agreeing, draft())).toEqual({ paired: true, rows: [] });
});

test('member rows keep each reason a member stays unchanged, a list left out for its characters, length or format with its own, and an unpaired member', () => {
  for (const reason of ['noTrackCredit', 'placeholder', 'notApplicable', 'size', 'format', 'characters', 'length'] as const) {
    const value = withApplied(applied => { applied.conflicts.splice(2, 1); applied.flagged.push({ path: `tracks.${slotId}.artists`, reason }); });
    expect(memberRows(value, draft())!.rows[0]).toEqual({ slotId, state: 'unchanged', reason });
  }
  const unpaired = withApplied(applied => { applied.conflicts.splice(2, 1); applied.pairs = applied.pairs!.filter(pair => pair.slotId !== slotId); });
  expect(memberRows(unpaired, draft())!.rows[0]).toEqual({ slotId, state: 'unchanged', reason: 'unpaired' });
});

test('without a single pairing every member is unchanged as unpaired, and without an applied candidate there are no member rows', () => {
  expect(memberRows(withApplied(applied => { applied.pairs = null; }), draft())).toEqual({ paired: false, rows: [
    { slotId, state: 'unchanged', reason: 'unpaired' }, { slotId: slotTwo, state: 'unchanged', reason: 'unpaired' }] });
  expect(memberRows(withApplied(applied => { applied.choice = 'none'; }), draft())).toBeNull();
  expect(memberRows({ ...lookup(), applied: null }, draft())).toBeNull();
  expect(memberRows(null, draft())).toBeNull();
  // An earlier run's application is still the review's, and its member rows still show: its conflicts still need answers.
  expect(memberRows({ ...lookup(), run: 2 }, draft())!.rows).toHaveLength(2);
});

test('expected rows place members by Disc and Track Number, a missing disc as disc 1; members at no row are outside', () => {
  const rows = reviewRows(), tracks = [{ slotId, discNumber: null, trackNumber: 1 }, { slotId: slotTwo, discNumber: 1, trackNumber: 1 }, { slotId: slotThree, discNumber: 2, trackNumber: 3 }];
  expect(expectedRowMembers(rows, tracks)).toEqual({ rows: [{ row: rows[0], slotIds: [slotId, slotTwo] }, { row: rows[1], slotIds: [] }, { row: rows[2], slotIds: [] }],
    outside: [slotThree], noFile: 2 });
  expect(expectedRowMembers(rows, [{ slotId, discNumber: 1, trackNumber: null }])).toMatchObject({ outside: [slotId], noFile: 3 });
  expect(expectedRowMembers(rows, [])).toEqual({ rows: rows.map(row => ({ row, slotIds: [] })), outside: [], noFile: 3 });
});

test('a number lookup filled through its pairing is held while the draft keeps it; an answered, edited or unpaired one is not', () => {
  expect([...pairingFilledNumbers(lookup(), draft())]).toEqual([`tracks.${slotTwo}.trackNumber`]);
  const both = withApplied(applied => { applied.values.push({ path: `tracks.${slotId}.discNumber`, slotId }); });
  const discs = draft(); discs.tracks[0].discNumber = 1;
  expect([...pairingFilledNumbers(both, discs)]).toEqual([`tracks.${slotTwo}.trackNumber`, `tracks.${slotId}.discNumber`]);
  // Edited since, answered from a conflict (the administrator's), no pairing, none applied or no read: nothing is held.
  const edited = draft(); edited.tracks[1].trackNumber = 4;
  expect(pairingFilledNumbers(lookup(), edited).size).toBe(0);
  expect(pairingFilledNumbers(withApplied(applied => { applied.conflicts.push({ path: `tracks.${slotTwo}.trackNumber`, slotId: slotTwo, lookup: 3, answer: 'lookup', musicBrainzId: false, precision: false }); }), draft()).size).toBe(0);
  expect(pairingFilledNumbers(withApplied(applied => { applied.pairs = null; }), draft()).size).toBe(0);
  expect(pairingFilledNumbers(withApplied(applied => { applied.choice = 'none'; }), draft()).size).toBe(0);
  expect(pairingFilledNumbers(null, draft()).size).toBe(0);
  // Titles and Artist entries are never numbers.
  expect(pairingFilledNumbers(withApplied(applied => { applied.values = [{ path: `tracks.${slotId}.title`, slotId }, { path: `tracks.${slotTwo}.artists`, slotId: slotTwo }]; }), draft()).size).toBe(0);
});

test('answers are made against the saved draft values, an absent value as null', () => {
  const saved = draft(), { expectedTracklist: _rows, ...album } = saved.album;
  expect(lookupAnswers([{ path: 'album.title' }, { path: `tracks.${slotId}.artists` }], saved, 'lookup')).toEqual([
    { path: 'album.title', answer: 'lookup', base: saved.album.title }, { path: `tracks.${slotId}.artists`, answer: 'lookup', base: saved.tracks[0].artists }]);
  expect(lookupAnswers([{ path: 'album.expectedTracklist' }, { path: 'album.label' }], { ...saved, album }, 'mine')).toEqual([
    { path: 'album.expectedTracklist', answer: 'mine', base: null }, { path: 'album.label', answer: 'mine', base: null }]);
});

const create = (identity: string | null, boundName: string): ReviewDecisionItem => ({ scope: identity ? 'artist' : 'label', identity, boundName, action: 'create-distinct', candidateId: null, candidateRevision: null });
const reuse = (identity: string, boundName: string, candidateId: string): ReviewDecisionItem => ({ scope: 'artist', identity, boundName, action: 'reuse', candidateId, candidateRevision: 'c'.repeat(64) });

test('the decision set sends each edit, else the saved decision without the ID the server binds, and a cleared edit drops its saved decision', () => {
  const data = reviewIdentityResponse();
  data.identities[1].decision = { ...reuse(leadHandle, 'Synthetic catalog Artist', leadRecordId), action: 'replace', candidateRevision: 'b'.repeat(64), boundMusicBrainzId: '00000000-0000-4000-8000-0000000000a1' };
  data.label = { name: 'Synthetic Label', musicBrainzId: null, state: 'unbound', bound: null, decision: { ...create(null, 'Synthetic Label'), boundMusicBrainzId: null }, preselection: null, needsAnswer: false, musicBrainzIdWrite: null };
  const stored = effectiveDecisions(data, new Map());
  expect(stored).toEqual([{ ...reuse(leadHandle, 'Synthetic catalog Artist', leadRecordId), action: 'replace', candidateRevision: 'b'.repeat(64) }, create(null, 'Synthetic Label')]);
  expect(stored.every(item => Object.keys(item).sort().join() === 'action,boundName,candidateId,candidateRevision,identity,scope')).toBe(true);
  const edits = new Map<string, DecisionEdit>([[guestHandle, { name: 'Synthetic guest', decision: create(guestHandle, 'Synthetic guest') }], [leadHandle, { name: 'Synthetic catalog Artist', decision: null }]]);
  expect(effectiveDecisions(data, edits)).toEqual([create(guestHandle, 'Synthetic guest'), create(null, 'Synthetic Label')]);
});

test('unsaved edits are pruned when their row vanished, was renamed, or now equals the saved decision', () => {
  const data = reviewIdentityResponse(), guest = create(guestHandle, 'Synthetic guest');
  const edits = new Map<string, DecisionEdit>([[guestHandle, { name: 'Synthetic guest', decision: guest }], [leadHandle, { name: 'Synthetic catalog Artist', decision: null }],
    ['70000000-0000-4000-8000-000000000099', { name: 'Gone', decision: create('70000000-0000-4000-8000-000000000099', 'Gone') }]]);
  // An edit to the decision the row already has (none) changes nothing.
  expect([...pruneDecisionEdits(edits, data).keys()]).toEqual([guestHandle]);
  data.identities[0].decision = { ...guest, boundMusicBrainzId: null };
  expect(pruneDecisionEdits(edits, data).size).toBe(0);
  const renamed = reviewIdentityResponse(); renamed.identities[0].name = 'Synthetic renamed guest';
  expect(pruneDecisionEdits(edits, renamed).size).toBe(0);
});

test('a candidate another identity of the same list is bound to, decided or preselected to reuse is taken; another list takes nothing', () => {
  const data = reviewIdentityResponse(), other = '70000000-0000-4000-8000-000000000003', elsewhere = '70000000-0000-4000-8000-000000000004';
  const row = (id: string, path: string) => ({ ...data.identities[0], id, name: id, entries: [{ ...data.identities[0].entries[0], path }] });
  data.identities.push({ ...row(other, 'album.artists'), preselection: { scope: 'artist', identity: other, boundName: other, action: 'reuse', candidateId: '141414141414141414141414', candidateRevision: 'd'.repeat(64) } },
    { ...row(elsewhere, `tracks.${slotId}.artists`), decision: { ...reuse(elsewhere, elsewhere, guestCandidateId), boundMusicBrainzId: null } });
  // The lead's bound record and the other Album entry's preselected reuse are taken for the guest (it shares the Album's list).
  expect([...takenCandidates(data, guestHandle, new Map())].sort()).toEqual([leadRecordId, '141414141414141414141414']);
  // A decision overrides the preselection, and an edit the decision.
  expect([...takenCandidates(data, guestHandle, new Map([[other, { name: other, decision: reuse(other, other, '151515151515151515151515') }]]))].sort()).toEqual([leadRecordId, '151515151515151515151515']);
  expect([...takenCandidates(data, guestHandle, new Map([[other, { name: other, decision: create(other, other) }]]))]).toEqual([leadRecordId]);
  // The guest's own reuse is not taken from itself, and the label shares no list.
  expect(takenCandidates(data, elsewhere, new Map())).toEqual(new Set());
  expect(takenCandidates(data, 'label', new Map())).toEqual(new Set());
});

test('a saved reuse or replace whose record changed since is stale: shown undecided, left out of the saved set and taking nothing; a current one is kept', () => {
  const data = reviewIdentityResponse(), guest = 'Synthetic guest', lead = 'Synthetic catalog Artist';
  // Listed at the revision decided: current, for a candidate and for the bound record a replace names.
  data.identities[0].decision = { ...reuse(guestHandle, guest, guestCandidateId), boundMusicBrainzId: null };
  data.identities[1].decision = { ...reuse(leadHandle, lead, leadRecordId), action: 'replace', candidateRevision: 'b'.repeat(64), boundMusicBrainzId: null };
  expect(effectiveDecisions(data, new Map()).map(item => item.identity)).toEqual([guestHandle, leadHandle]);
  expect(rowDecision(data, guestHandle, new Map())).toEqual({ decision: reuse(guestHandle, guest, guestCandidateId), stale: false });
  // Listed at another revision (edited since), or no longer listed (renamed): stale.
  for (const stale of [{ ...data, candidates: { ...data.candidates, items: [{ ...data.candidates.items[0], revision: 'e'.repeat(64) }] } },
    { ...data, candidates: { ...data.candidates, items: [] } }]) {
    expect(effectiveDecisions(stale, new Map()).map(item => item.identity)).toEqual([leadHandle]);
    expect(rowDecision(stale, guestHandle, new Map())).toEqual({ decision: null, stale: true });
    // A new choice answers the row again and is sent; the stale reuse names no candidate for another entry of the list.
    const edits = new Map<string, DecisionEdit>([[guestHandle, { name: guest, decision: create(guestHandle, guest) }]]);
    expect(rowDecision(stale, guestHandle, edits)).toEqual({ decision: create(guestHandle, guest), stale: false });
    expect(effectiveDecisions(stale, edits)).toEqual([create(guestHandle, guest), { ...reuse(leadHandle, lead, leadRecordId), action: 'replace', candidateRevision: 'b'.repeat(64) }]);
  }
  const shared = '70000000-0000-4000-8000-000000000005', withShared = reviewIdentityResponse();
  withShared.identities.push({ ...withShared.identities[0], id: shared, name: shared, decision: { ...reuse(shared, shared, guestCandidateId), candidateRevision: 'e'.repeat(64), boundMusicBrainzId: null } });
  expect(takenCandidates(withShared, guestHandle, new Map()).has(guestCandidateId)).toBe(false);
  withShared.identities[2].decision!.candidateRevision = 'c'.repeat(64);
  expect(takenCandidates(withShared, guestHandle, new Map()).has(guestCandidateId)).toBe(true);
  // A bound replace whose record is at another revision is stale too, and a create never is.
  const replaced = reviewIdentityResponse();
  replaced.identities[1].decision = { ...reuse(leadHandle, lead, leadRecordId), action: 'replace', candidateRevision: 'f'.repeat(64), boundMusicBrainzId: null };
  replaced.identities[0].decision = { ...create(guestHandle, guest), boundMusicBrainzId: null };
  expect(effectiveDecisions(replaced, new Map())).toEqual([create(guestHandle, guest)]);
  expect(rowDecision(replaced, leadHandle, new Map()).stale).toBe(true);
});
